```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

const MAX_QUESTION_BYTES: usize = 512;
const NO_KNOWLEDGE: &str = "no matching knowledge-base entries";

struct Node;

/// `requires` guarantees the input is within bound; this keeps the
/// `ensures` on the output true even if that precondition is violated,
/// truncating at a char boundary so the result stays valid UTF-8.
fn bounded(mut question: String) -> String {
    if question.len() <= MAX_QUESTION_BYTES {
        return question;
    }
    let mut end = MAX_QUESTION_BYTES;
    while !question.is_char_boundary(end) {
        end -= 1;
    }
    question.truncate(end);
    question
}

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let CustomerQuery {
            intent,
            entities: _,
            question,
        } = query.query;

        let question = bounded(question);

        let mut knowledge = kb_read::lookup(&question);
        if knowledge.is_empty() {
            knowledge.push(NO_KNOWLEDGE.to_string());
        }

        ConversationContext {
            intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
```

